/**
 * Addresses the app is handed at run time and then sends somebody to: the
 * download page named in the site's version file, the checkout an operator
 * typed into a promotion code, and the billing provider's portal. Each one
 * is checked here before it is opened, so a compromised site deploy, a
 * mistyped or malicious promotion, or a tampered response cannot turn the
 * app into a phishing redirect. React already refuses `javascript:` in an
 * href; this is the rest: https only, no user name or password in the
 * address, no odd port, and a host from the list for that purpose.
 *
 * The lists live in code rather than in data on purpose, like the consent
 * screen's (`features/connect/redirect.ts`): they are a security boundary,
 * and a list fetched at run time could be changed by the very thing it
 * guards against. This module is the one place they are written; screens
 * call `safeExternalUrl` and never compare hosts themselves.
 */

/** The public site, which serves the version file and the Android download page. */
export const SITE_HOST = 'lexpad.app';

/**
 * Lexpad's Google Play listing. Inside the Android app the update line opens
 * this, never an address from the version file: written here because it is a
 * security boundary (see above), and the package id is fixed for ever.
 */
export const PLAY_LISTING_URL = 'https://play.google.com/store/apps/details?id=app.lexpad.android';

/**
 * Lexpad for Windows in the Microsoft Store (Store ID 9NSFK2ZK6PFS, live
 * since 2026-10-10). The desktop app's update line opens this, never an
 * address from the version file, for the same reason as the Play listing.
 */
export const MICROSOFT_STORE_URL = 'https://apps.microsoft.com/detail/9NSFK2ZK6PFS';

/** What an address is for; each purpose has its own hosts. */
export type ExternalPurpose = 'update' | 'store' | 'checkout' | 'billingPortal';

/**
 * Hosts allowed for each purpose. `exact` must equal the host; `under`
 * also allows any subdomain of it (Paddle serves live and sandbox from
 * different subdomains, and a checkout link may sit on one of ours).
 */
const ALLOWED: Record<ExternalPurpose, { exact: readonly string[]; under: readonly string[] }> = {
  // The sideloaded Android build's and the desktop app's download pages, from lexpad.app/version.json.
  update: { exact: [SITE_HOST], under: [] },
  // The store listings the update line opens: Google Play (Android), the Microsoft Store (Windows).
  store: { exact: ['play.google.com', 'apps.microsoft.com'], under: [] },
  // A promotion's checkout: Paddle's hosted checkout or a page of ours.
  checkout: { exact: [SITE_HOST], under: [SITE_HOST, 'paddle.com', 'paddle.io'] },
  // Paddle's customer portal (customer-portal.paddle.com and its sandbox twin).
  billingPortal: { exact: [], under: ['paddle.com'] },
};

/** The parsed address when it is safe to send somebody to for `purpose`, otherwise undefined. */
export function safeExternalUrl(raw: unknown, purpose: ExternalPurpose): URL | undefined {
  if (typeof raw !== 'string' || raw.length === 0) return undefined;
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return undefined;
  }
  if (url.protocol !== 'https:' || url.username !== '' || url.password !== '' || url.port !== '') {
    return undefined;
  }
  const host = url.hostname.toLowerCase();
  const { exact, under } = ALLOWED[purpose];
  if (exact.includes(host) || under.some((h) => host.endsWith(`.${h}`))) return url;
  return undefined;
}

/**
 * How long a notification's address may be: the contract's own cap
 * (`NotificationActionInput.url`, maxLength 500), repeated here because this
 * check must refuse anything the server would have refused.
 */
export const NOTIFICATION_URL_MAX = 500;

/** Four numbers with dots, or anything in brackets: an address by number, never a name. */
const IP_HOST = /^(\d{1,3}\.){3}\d{1,3}$|^\[.*\]$/;

/**
 * A notification's external link, checked again here before its button is
 * drawn or pressed. Unlike the purposes above, its hosts are data: the
 * server's `notification_links` flag, sent as `ClientConfig.linkHosts`
 * (owner, 21 Oct 2026). The server already checked the address when the
 * message was sent and again when the inbox was listed; this guards against
 * a stale copy on the device or a tampered payload, not a compromised API.
 * No list (external links switched off, or the server not reached) opens
 * nothing. The rules are the server's: https, no user name, password or
 * port, a host equal to one listed (no subdomains, no wildcards, no IP), no
 * placeholder braces, at most NOTIFICATION_URL_MAX characters. Nothing is
 * ever added to the address.
 */
export function safeNotificationUrl(raw: unknown, hosts: readonly string[] | undefined): URL | undefined {
  if (hosts === undefined || hosts.length === 0) return undefined;
  if (typeof raw !== 'string' || raw.length === 0 || raw.length > NOTIFICATION_URL_MAX) return undefined;
  if (/[{}]|%7b|%7d/i.test(raw)) return undefined;
  if (!raw.startsWith('https://')) return undefined;
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return undefined;
  }
  if (url.protocol !== 'https:' || url.username !== '' || url.password !== '' || url.port !== '') {
    return undefined;
  }
  const host = url.hostname.toLowerCase();
  if (IP_HOST.test(host)) return undefined;
  return hosts.some((allowed) => allowed.toLowerCase() === host) ? url : undefined;
}
